mapper.update:
UPDATE SYT9MG
   SET TR_YMD      = TO_DATE(REPLACE(#{trYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
     , TR_CD       = #{trCd, jdbcType=VARCHAR}
     , FUND_CD     = #{fundCd, jdbcType=VARCHAR}
     , TRUSTEE     = #{trustee, jdbcType=VARCHAR}
     , JM_CD       = #{hjCd, jdbcType=VARCHAR}
     , TR_SEQ      = COALESCE(#{trSeq, jdbcType=NUMERIC}, 1)
     , AEK_GB      = COALESCE(#{aekGb, jdbcType=VARCHAR}, '1')
     , CURRENCY    = #{currency, jdbcType=VARCHAR}
     , TR_CO_CD    = #{trCoCd, jdbcType=VARCHAR}
     , AEK         = COALESCE(#{aek, jdbcType=NUMERIC}, 0)
     , JAN_AEK     = COALESCE(#{janAek, jdbcType=NUMERIC}, 0)
     , WON_AEK     = COALESCE(#{wonAek, jdbcType=NUMERIC}, 0)
     , WON_JAN_AEK = COALESCE(#{wonJanAek, jdbcType=NUMERIC}, 0)
     , SANGHW_YMD  = CASE WHEN #{sanghwYmd, jdbcType=VARCHAR} IS NOT NULL AND #{sanghwYmd, jdbcType=VARCHAR} != '' THEN TO_DATE(REPLACE(#{sanghwYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD') ELSE NULL END
     , BF_YMD      = CASE WHEN #{bfYmd, jdbcType=VARCHAR} IS NOT NULL AND #{bfYmd, jdbcType=VARCHAR} != '' THEN TO_DATE(REPLACE(#{bfYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD') ELSE NULL END
     , AF_YMD      = CASE WHEN #{afYmd, jdbcType=VARCHAR} IS NOT NULL AND #{afYmd, jdbcType=VARCHAR} != '' THEN TO_DATE(REPLACE(#{afYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD') ELSE NULL END
     , BIGO        = #{bigo, jdbcType=VARCHAR}
     , GWAMOK      = #{gwamok, jdbcType=VARCHAR}
 WHERE CORP_GR = #{corpGr, jdbcType=VARCHAR}
   AND TR_YMD  = TO_DATE(REPLACE(COALESCE(#{origTrYmd, jdbcType=VARCHAR}, #{trYmd, jdbcType=VARCHAR}), '-', ''), 'YYYYMMDD')
   AND TR_CD   = COALESCE(#{origTrCd, jdbcType=VARCHAR}, #{trCd, jdbcType=VARCHAR})
   AND FUND_CD = COALESCE(#{origFundCd, jdbcType=VARCHAR}, #{fundCd, jdbcType=VARCHAR})
   AND JM_CD   = COALESCE(#{origHjCd, jdbcType=VARCHAR}, #{hjCd, jdbcType=VARCHAR})
   AND TR_SEQ  = COALESCE(#{origTrSeq, jdbcType=NUMERIC}, #{trSeq, jdbcType=NUMERIC})
   AND AEK_GB  = COALESCE(#{origAekGb, jdbcType=VARCHAR}, #{aekGb, jdbcType=VARCHAR})

UPDATE SYT9MG_TR
   SET SANGHW_YMD     = TO_DATE(REPLACE(#{sanghwYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
     , TRUSTEE        = #{trustee, jdbcType=VARCHAR}
     , CURRENCY       = #{currency, jdbcType=VARCHAR}
     , TR_CO_CD       = #{trCoCd, jdbcType=VARCHAR}
     , SANGHW_AEK     = COALESCE(#{sanghwAek, jdbcType=NUMERIC}, 0)
     , WON_SANGHW_AEK = COALESCE(#{wonSanghwAek, jdbcType=NUMERIC}, 0)
     , GIJUN_RT       = COALESCE(#{gijunRt, jdbcType=NUMERIC}, 0)
     , JAN_AEK        = COALESCE(#{janAek, jdbcType=NUMERIC}, 0)
     , WON_JAN_AEK    = COALESCE(#{wonJanAek, jdbcType=NUMERIC}, 0)
     , WON_HWAN_CHA   = COALESCE(#{wonHwanCha, jdbcType=NUMERIC}, 0)
     , FCUR_JAN_AEK   = COALESCE(#{fcurJanAek, jdbcType=NUMERIC}, 0)
     , FCUR_HWAN_CHA  = COALESCE(#{fcurHwanCha, jdbcType=NUMERIC}, 0)
 WHERE CORP_GR    = #{corpGr, jdbcType=VARCHAR}
   AND TR_YMD     = TO_DATE(REPLACE(#{trYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
   AND TR_CD      = #{trCd, jdbcType=VARCHAR}
   AND FUND_CD    = #{fundCd, jdbcType=VARCHAR}
   AND JM_CD      = #{hjCd, jdbcType=VARCHAR}
   AND TR_SEQ     = COALESCE(#{trSeq, jdbcType=NUMERIC}, 1)
   AND AEK_GB     = COALESCE(#{aekGb, jdbcType=VARCHAR}, '1')
   AND SANGHW_YMD = TO_DATE(REPLACE(COALESCE(#{origSanghwYmd, jdbcType=VARCHAR}, #{sanghwYmd, jdbcType=VARCHAR}), '-', ''), 'YYYYMMDD')

